public interface AssignmentPolicy {
    Optional<Vehicle> choose(Trip trip, List<Vehicle> candidates);
}

public class NearestVehiclePolicy implements AssignmentPolicy {
    private final double maxRadiusKm;

    public NearestVehiclePolicy(double maxRadiusKm) {
        this.maxRadiusKm = maxRadiusKm;
    }

    @Override
    public Optional<Vehicle> choose(Trip trip, List<Vehicle> candidates) {
        Vehicle best = null;
        double bestKm = Double.MAX_VALUE;
        for (Vehicle v : candidates) {
            if (v.getSeats() < trip.getPassengers()) continue;
            double km = GeoUtil.distanceKm(v.getPosition(), trip.getPickup());
            if (km < bestKm) {
                best = v;
                bestKm = km;
            }
        }
        return Optional.ofNullable(best);
    }
}

public class Vehicle {
  private final String id;
  private GeoPoint position;
  private VehicleStatus status;
  private final int seats;
  public Vehicle(String id, GeoPoint position, int seats)
  public String getId()
  public GeoPoint getPosition()
  public int getSeats()
  public VehicleStatus getStatus()
  public void moveTo(GeoPoint p)
  public void assign()
  public void release()
  public void sendToMaintenance()
}

public Optional<Vehicle> assign(Trip trip) {
    Optional<Vehicle> chosen = policy.choose(trip, repository.findAvailable());
    chosen.ifPresent(v -> {
        v.assign();
        trip.assignTo(v);
        repository.save(v);
    });
    return chosen;
}

public DispatchService(VehicleRepository repository, AssignmentPolicy policy) {
    this.repository = repository;
    this.policy = policy;
}

@Test
void skipsVehiclesWithTooFewSeats() {
    NearestVehiclePolicy policy = new NearestVehiclePolicy(50);
    Trip trip = new Trip("t", new GeoPoint(0, 0), new GeoPoint(1, 1), 6);
    assertTrue(policy.choose(trip, List.of(new Vehicle("small", new GeoPoint(0, 0), 4))).isEmpty());
}
